import java.util.*; public class Q09_OnlineCoursePlatform{static class Course{String n,d;Course(String n,String d){this.n=n;this.d=d;}}static class Student{String n;Course c;Student(String n,Course c){this.n=n;this.c=c;}public String toString(){return "Student: "+n+" Course: "+c.n+" ("+c.d+")";}}static class Premium extends Student{double discount;Premium(String n,Course c,double d){super(n,c);discount=d;}public String toString(){return "Premium Student: "+n+" Course: "+c.n+" ("+c.d+") Discount: "+discount+"%";}}public static void main(String[]x){Scanner s=new Scanner(System.in);String[]c=s.nextLine().split(",",2);Course course=new Course(c[0],c[1]);while(s.hasNextLine()){String[]p=s.nextLine().split(",");if(p.length==2)System.out.println(new Student(p[0],course));else System.out.println(new Premium(p[0],course,Double.parseDouble(p[2])));}}}
